#!/usr/bin/env python3
from pathlib import Path
import json,hashlib,datetime,csv
OUT=Path(__file__).resolve().parent;EX=OUT.parent/'fs_ewc_rq2_20260920/execution'
def info(p):
 p=Path(p);return {'path':str(p),'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
result={'checked_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'mode':'read only; no GPU/training/queue changes','runs':[]};rows=[];rngs={}
for method in ['sgd','gam']:
 d=EX/'training'/f'A_{method}_to_sgd_seed0';manifest=json.loads((d/'run_manifest.json').read_text());comp=json.loads((d/'COMPLETE.json').read_text());mp=next(d.rglob('*cl_metrics.json'));x=json.loads(mp.read_text());loc=[json.loads(l) for l in (d/'task0_local_metrics.jsonl').read_text().splitlines()];assert len(loc)==2
 cfg=manifest['config'];a=x['cnn']['matrices']['final'];m=x['mechanism']['steps']['1'];rngs[method]=[json.loads(l) for l in (d/'rng_receipts.jsonl').read_text().splitlines()]
 row={'method':method,'a11_fp32':loc[0]['test']['seen_accuracy'],'a11_historical_inherited':a[0][0],'a21_fp32':loc[1]['test']['seen_accuracy'],'a22_trainer_rounded':a[1][1],'bwt_fp32':loc[1]['test']['seen_accuracy']-loc[0]['test']['seen_accuracy'],'r_eff_recorded':loc[1]['effective_weight_displacement'],'delta_norm_squared':m['delta_norm'],'test_local_loss_start':loc[0]['test']['local_ce'],'test_local_loss_end':loc[1]['test']['local_ce'],'test_local_loss_increment':loc[1]['test']['local_ce']-loc[0]['test']['local_ce'],'test_seen_loss_increment':loc[1]['test']['seen_ce']-loc[0]['test']['seen_ce'],'train_local_loss_increment':loc[1]['train']['local_ce']-loc[0]['train']['local_ce']}
 rows.append(row)
 result['runs'].append({'method':method,'status':comp['status'],'completion_utc':datetime.datetime.fromtimestamp(comp['time_unix'],datetime.timezone.utc).isoformat(),'manifest':info(d/'run_manifest.json'),'config':cfg,'complete_receipt':info(d/'COMPLETE.json'),'metrics':info(mp),'local_metrics':info(d/'task0_local_metrics.jsonl'),'rng_receipts':info(d/'rng_receipts.jsonl'),'runtime_receipts':info(d/'runtime_receipts.jsonl'),'anchor_checkpoint':str(Path(cfg['resume_from_checkpoint_dir'])/'task_00.pt'),'endpoint_checkpoint':str(d/'checkpoints/task_01.pt'),'endpoint_exists':(d/'checkpoints/task_01.pt').is_file(),'numerical_results':row,'pointers':{'historical_a11':'metrics:/cnn/matrices/final/0/0','a21_a22':'metrics:/cnn/matrices/final/1','energy':'metrics:/mechanism/steps/1/delta_norm','current_fp32_a11':'local_metrics:jsonl_line1/test/seen_accuracy','current_fp32_a21':'local_metrics:jsonl_line2/test/seen_accuracy'},'limitations':['raw Task1 per-example Fisher endpoint evaluation is still blocked; trace_measured=False in local metrics','historical accuracy matrix first row is inherited, not current FP32 reevaluation; use explicit local receipt for a11','single seed mechanism case']})
fields=['dataset_ids_sha256','generator_seed','indices_sha256','first_batch_pixels_targets_sha256','samples','batches','iteration','loader_serial','task']
train={k:[{f:v.get(f) for f in fields} for v in vs if v['event']=='loader_iteration' and v.get('shuffle')] for k,vs in rngs.items()}
heads={k:[v['new_head_sha256'] for v in vs if v['event']=='head_initialized'] for k,vs in rngs.items()}
result['paired_rng_check']={'head_sha256':heads,'head_equal':heads['sgd']==heads['gam'],'training_loader_passes':{k:len(v) for k,v in train.items()},'all_51_shuffle_loader_pass_records_equal':train['sgd']==train['gam'],'scope':'same head init and ordered sample IDs plus first-batch pixel/target hash per shuffled loader pass; does not hash every augmented batch pixel'}
p=EX/'campaign_seed0_dualline_gpu03/pipeline_state.json';st=json.loads(p.read_text());result['pipeline_snapshot']={'source':info(p),'updated_utc':st['updated_utc'],'status':st['status'],'jobs':{k:v['status'] for k,v in st['jobs'].items()},'error':st.get('error')}
(OUT/'today_a_sources.json').write_text(json.dumps(result,indent=2,ensure_ascii=False)+'\n')
with (OUT/'today_a_completed_results.csv').open('w') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
p=OUT/'new_lora_sources.json';old=json.loads(p.read_text());old['current_diagnostics']['pipeline_snapshot']=result['pipeline_snapshot'];old['current_diagnostics']['today_training']=info(OUT/'today_a_sources.json');old['current_diagnostics']['latest_checked_utc']=result['checked_utc'];p.write_text(json.dumps(old,indent=2,ensure_ascii=False)+'\n')
print(result['checked_utc']);print(json.dumps(rows,indent=2));print(result['paired_rng_check']);print(result['pipeline_snapshot']['status'],result['pipeline_snapshot']['updated_utc'])
